const webhookData = $("Webhook").first().json;
const body = webhookData.body || webhookData;

const manuscript = $("Fetch Manuscript Data").first()?.json || {};
const progressResults = $("Fetch Publishing Progress").all();
const progress = progressResults.length > 0 ? progressResults[0].json : {};

console.log("📚 Building Taylor context:", {
  manuscriptId: body.manuscriptId,
  hasManuscript: !!manuscript.title,
  hasProgress: !!progress.assessment_completed,
  hasSummary: !!manuscript.manuscript_summary,
});

// Handle missing publishing progress gracefully
const safeProgress = {
  selected_cover_url: progress.selected_cover_url || null,
  current_step: progress.current_step || "assessment",
  assessment_completed: progress.assessment_completed || false,
  publishing_goal: progress.publishing_goal || "not specified",
  experience: progress.experience || "not specified", // ✅ Changed from experience_level
  timeline: progress.timeline || "not specified",
  platforms: progress.platforms || [], // ✅ Added platforms
  formats: progress.formats || [], // ✅ Added formats
  cover_concepts: progress.cover_concepts || [],
  cover_generation_status: progress.cover_generation_status || null,
};

// Build comprehensive context
const context = {
  // Manuscript basics
  manuscriptTitle: manuscript.title || "Untitled",
  genre: manuscript.genre || "Fiction",
  wordCount: manuscript.current_word_count || 0,
  chapterCount: manuscript.total_chapters || 0,

  // Manuscript summary
  summary: manuscript.manuscript_summary || "Summary not available",

  // Publishing context (with safe defaults)
  hasCover: !!safeProgress.selected_cover_url,
  coverUrl: safeProgress.selected_cover_url,
  currentStep: safeProgress.current_step,
  assessmentComplete: safeProgress.assessment_completed,
  publishingGoal: safeProgress.publishing_goal,
  experience: safeProgress.experience, // ✅ Changed from experienceLevel
  timeline: safeProgress.timeline,
  platforms: safeProgress.platforms, // ✅ Added
  formats: safeProgress.formats, // ✅ Added
  // Cover information
  coverConcepts: safeProgress.cover_concepts,
  coverCount: Array.isArray(safeProgress.cover_concepts)
    ? safeProgress.cover_concepts.length
    : 0,
  coverGenerationStatus: safeProgress.cover_generation_status,

  // Author's current message
  authorMessage: body.message,
  authorFirstName: body.authorFirstName || "there",
};

console.log("✅ Taylor context built successfully");

return { json: context };

