const promptData = $input.first().json;

return {
  json: {
    model: "claude-sonnet-4-20250514",
    max_tokens: 4096,
    temperature: 0.8,
    system: promptData.systemPrompt,
    messages: [
      {
        role: "user",
        content: promptData.userPrompt,
      },
    ],
    tools: [
      {
        name: "generate_covers",
        description:
          "Generate 4 professional AI cover designs based on user's preferences. Only use this tool when the user explicitly requests cover creation or design. Do NOT use for discussing cover concepts or gathering preferences.",
        input_schema: {
          type: "object",
          properties: {
            mood: {
              type: "string",
              description:
                "The atmosphere or emotional tone (e.g., 'dark and mysterious', 'bright and uplifting', 'atmospheric and moody')",
            },
            colors: {
              type: "string",
              description:
                "Specific color palette or color families (e.g., 'deep blues and purples', 'warm earth tones', 'black and gold')",
            },
            elements: {
              type: "string",
              description:
                "Visual elements or imagery to include (e.g., 'forest scene with magical effects', 'urban skyline', 'abstract geometric shapes')",
            },
            style: {
              type: "string",
              description:
                "Overall visual style (e.g., 'cinematic and detailed', 'minimalist', 'illustrated', 'photographic')",
            },
          },
          required: ["mood", "colors", "elements"],
        },
      },
    ],
  },
};

const apiResponse = $input.first().json;

console.log("🤖 Claude API Response:", JSON.stringify(apiResponse, null, 2));

const content = apiResponse.content || [];
const toolUse = content.find((block) => block.type === "tool_use");
const textBlock = content.find((block) => block.type === "text");

if (toolUse) {
  console.log("🔧 Tool use detected:", toolUse.name);
  console.log("📋 Tool input:", JSON.stringify(toolUse.input, null, 2));

  return {
    json: {
      responseType: "tool_use",
      toolName: toolUse.name,
      toolInput: toolUse.input,
      toolUseId: toolUse.id,
      hasText: !!textBlock,
      textResponse: textBlock?.text || "",
    },
  };
} else if (textBlock) {
  console.log("💬 Text response detected");

  return {
    json: {
      responseType: "text",
      textResponse: textBlock.text,
    },
  };
} else {
  console.error("❌ Unexpected response format");

  return {
    json: {
      responseType: "error",
      textResponse:
        "I'm having trouble responding right now. Please try again.",
    },
  };
}

const toolData = $("Prepare Cover Generation").first().json;

return {
  json: {
    response:
      toolData.originalMessage ||
      "🎨 Perfect! I'm generating 4 professional cover designs based on your preferences. " +
        "This will take about 2-3 minutes. Your new covers will appear in the Cover Designer panel automatically!",
    success: true,
    action: "cover_generation_started",
  },
};

const responseData = $input.first().json;

return {
  json: {
    response: responseData.textResponse,
    success: true,
    action: "conversation",
  },
};

const webhookData = $("Webhook").first().json.body;
const toolData = $input.first().json;

console.log("🎨 Tool input:", toolData.toolInput);

const { mood, colors, elements, style } = toolData.toolInput;

return {
  json: {
    manuscriptId: webhookData.manuscriptId,
    genre: webhookData.manuscriptData?.genre || "fiction",
    mood: mood || "atmospheric, engaging",
    colors: colors || "genre-appropriate colors",
    elements: elements || "professional imagery",
    style: style || "cinematic, detailed",
    manuscriptTitle: webhookData.manuscriptData?.title || "the book",
    toolUseId: toolData.toolUseId,
    originalMessage: toolData.textResponse || "",
  },
};
